#include <cmath>
#include <cstdio>

// Cost-of-carry forward price. Use either a continuous yield q, or the PV I of
// lump income paid during the life - pass the other as 0.
double forwardPrice(double S, double r, double T, double q = 0.0, double incomePV = 0.0) {
    return (S - incomePV) * std::exp((r - q) * T);
}

int main() {
    std::printf("F, no income          = %.6f\n", forwardPrice(100.0, 0.05, 0.5));
    std::printf("F, dividend yield 2%%  = %.6f\n", forwardPrice(100.0, 0.05, 0.5, 0.02));
    std::printf("F, lump dividend PV=2 = %.6f\n", forwardPrice(100.0, 0.05, 0.5, 0.0, 2.0));
    const double S = 1800.0, r = 0.04, storagePV = 5.0 * std::exp(-0.04);
    std::printf("F, gold with storage  = %.6f\n", (S + storagePV) * std::exp(r));
    const double fair = forwardPrice(100.0, 0.05, 0.5);
    std::printf("arb profit if F=104   = %.6f (PV %.6f)\n", 104.0 - fair, (104.0 - fair) * std::exp(-0.025));
    return 0;
}
